        if (!rn_q) begin aq_q[0] <= 1'b0; aq_q[21] <= 1'b0; am_q[0] <= 1'b0; xq[10:0] <= 11'd0; pxq[0] <= 1'b0; pyq[0] <= 1'b0;
                         zq[0] <= 1'b0; fx_q <= 1'b0; fy_q <= 1'b0; fz_q <= 1'b0; end
        else begin aq_q[0] <= aq[0]; aq_q[21] <= aq[21]; am_q[0] <= am[0]; xq[10:0] <= xi[10:0]; pxq[0] <= px[0]; pyq[0] <= py[0];
                   zq[0] <= zi[0]; fx_q <= fx; fy_q <= fy; fz_q <= fz; end
    wire         start = aq_q[0];
    wire [13:0]  T = aq_q[14:1];
    // Compiler ages are measured in edges AFTER the local start edge.
    reg [15:0] schedule_age;
    reg schedule_active;
    always @(posedge ck or negedge rn_q)
        if (!rn_q) begin schedule_age<=0; schedule_active<=0; end
        else if (start) begin schedule_age<=0; schedule_active<=1; end
        else if (schedule_active && schedule_age!=16'hffff) schedule_age<=schedule_age+1'b1;

    // ---- stack geometry (the golden's expressions) ---------------------------------------------------------------------
    wire [13:0]  base_s = {5'd0, st_q, 7'd0};
    wire         any_s = T > base_s;
    wire [13:0]  rem = T - base_s;
    wire [4:0]   gmax_c = !any_s ? 5'd0 : ((rem >= 14'd128) ? 5'd16 : ((rem + 14'd7) >> 3));
    wire [13:0]  tail = {5'd0, T[8:0]};
    wire [13:0]  part = (tail > base_s) ? ((tail - base_s > 14'd128) ? 14'd128 : (tail - base_s)) : 14'd0;
    wire [11:0]  ns_c = {T[13:9], 7'd0} + part[11:0];
    wire [4:0]   nblk_c = !any_s ? 5'd0 : (((T - base_s - 14'd1) >> 9) + 14'd1);
    reg  [11:0]  n_s;
    reg  [4:0]   nblk;
    always @(posedge ck) begin n_s <= ns_c; nblk <= nblk_c; end
    // ---- K-pass completion and M count ---------------------------------------------------------------------------------
    reg  [11:0]  sc0, sc1;
    reg  [1:0]   kdone, lsent, zsent, pvd;
    reg  [2:0]   lh, mc0, mc1;
    reg  [4:0]   zn0, zn1;                             // block sums sent
    wire [1:0]   qgo = {(HEADS == 2) && kdone[1] && mc1 == 3'd4, kdone[0] && mc0 == 3'd4};
    // ---- Z block sums: a 16-entry queue, 4 messages each ---------------------------------------------------------------
    reg  [132:0] zf_m [0:15];                          // {sum 128, k 4, g}
    reg  [4:0]   zfw, zfr;
    reg  [1:0]   zh;
    reg          zovf;
    wire         z_ne = zfw != zfr;
    wire [132:0] z_hd;
    reg  [15:0]  zp;
    wire [3:0]   zf_wa = STATIC_SCHEDULE ? zq[5:2] : zfw[3:0];
    always @(posedge ck) if (zq[0] && stl == 7'd0) zf_m[zf_wa] <= {zq[137:10], zq[5:2], zq[1]};
    wire         legacy_l_pend = (kdone[0] && !lsent[0]) || (HEADS == 2 && kdone[1] && lsent[0] && !lsent[1]);
    wire         lg = lsent[0];
    wire         legacy_zd0 = !zsent[0] && qgo[0] && zn0 == nblk && !z_ne;
    wire         legacy_zd1 = (HEADS == 2) && !zsent[1] && zsent[0] && qgo[1] && zn1 == nblk && !z_ne;
    reg  [31:0] cal_q, cal_r;
    always @(posedge ck) cal_q <= cal;
    always @(posedge ck) if (start) cal_r <= cal_q;
    wire [15:0] lmax_age = cal_r[15:0], zst_age = cal_r[31:16];
    wire cal_bad = STATIC_SCHEDULE && schedule_active && (lmax_age < 16'd1 || zst_age < lmax_age+16'd4);
    wire l_slot = schedule_active && schedule_age >= lmax_age-16'd1 && schedule_age < lmax_age+16'd3;
    wire [15:0] z_age = schedule_age - (zst_age-16'd1);
    wire z_window = schedule_active && schedule_age >= zst_age-16'd1;
    wire z_slot = z_window && (z_age / Z_STRIDE < nblk) && (z_age % Z_STRIDE < 4);
    wire z_done_slot = z_window && z_age == nblk * Z_STRIDE;
    wire [3:0] z_k = 4'(z_age / Z_STRIDE);
    assign z_hd = zf_m[STATIC_SCHEDULE ? z_k : zfr[3:0]];
    wire z_have = STATIC_SCHEDULE ? zp[z_k] : z_ne;
    wire l_pend = STATIC_SCHEDULE ? l_slot : legacy_l_pend;
    wire z_emit = STATIC_SCHEDULE ? z_slot : z_ne;
    wire zd0 = STATIC_SCHEDULE ? z_done_slot : legacy_zd0;
    wire zd1 = STATIC_SCHEDULE ? 1'b0 : legacy_zd1;
    initial if (STATIC_SCHEDULE && (HEADS != 1 || Z_STRIDE < 4)) $fatal(1,"invalid static ASTK CTL profile");
    // ---- P.V: the two lanes carry the two halves of a beat on the same edge ---------------------------------------------
    reg  [6:0]   stl;                                  // restart: 96 cycles in which the lanes and the Z nodes drain
    wire         quiet = stl == 7'd0;
    wire         pv_v = pxq[0] && pyq[0] && quiet;
    wire         pv_bad = quiet && ((pxq[0] != pyq[0]) || (pv_v && pxq[6:1] != pyq[6:1]));
    wire         z_in = zq[0] && quiet;
    wire [255:0] pdx = (`KVD_AKMUT == 4) ? pyq[262:7] : pxq[262:7];
    wire [255:0] pdy = (`KVD_AKMUT == 4) ? pxq[262:7] : pyq[262:7];
    // a beat's 16 lanes: kk = 4 j + i / 4, bb = i % 4; X holds kk mod 4 = 0, 1 and Y 2, 3 (each {slot 1, slot 0} x 4 beats)
    wire [511:0] pvw = {pdy, pdx};
    reg  [31:0]  lm_s, z_s;
    integer m_;
    always @* begin
        lm_s = 32'd0; z_s = 32'd0;
        for (m_ = 0; m_ < 8; m_ = m_ + 1) if ({lg, lh[1:0]} == m_) lm_s = xq[11 + 32*m_ +: 32];
        for (m_ = 0; m_ < 4; m_ = m_ + 1) if (zh == m_) z_s = z_hd[5 + 32*m_ +: 32];
    end
    reg          f;
    always @(posedge ck or negedge rn_q)
        if (!rn_q) begin
            sc0 <= 12'd0; sc1 <= 12'd0; kdone <= 2'b00; lsent <= 2'b00; zsent <= 2'b00; pvd <= 2'b00; lh <= 3'd0; mc0 <= 3'd0;
            mc1 <= 3'd0; zn0 <= 5'd0; zn1 <= 5'd0; zfw <= 5'd0; zfr <= 5'd0; zh <= 2'd0; zovf <= 1'b0; f <= 1'b0; af <= 1'b0; zp <= 16'd0;
            ap[0] <= 1'b0; ap[45:43] <= 3'b000; lt[0] <= 1'b0; qo[0] <= 1'b0; qo[15] <= 1'b0; qo[536:534] <= 3'd0;
            co[0] <= 1'b0; stl <= 7'd0;
        end else begin
            lt[0] <= start; qo[0] <= start; qo[15] <= aq_q[21]; qo[535:534] <= kdone; qo[536] <= am_q[0]; co[0] <= start;
            ap[0] <= 1'b0; ap[45] <= pv_v; ap[44:43] <= pvd;
            af <= f | (quiet && (xq[0] | fx_q | fy_q | fz_q)) | zovf;
            if (pv_bad || cal_bad || (STATIC_SCHEDULE &&
                ((l_slot && !kdone[0]) || (z_slot && !z_have) || (z_in && zp[zq[5:2]]) ||
                 (z_slot && (z_hd[0] || z_hd[4:1] != z_age / Z_STRIDE)) ||
                 (z_done_slot && (!qgo[0] || zn0 != nblk || z_ne))))) f <= 1'b1;
            if (pv_v && pxq[5:1] == 5'd31) pvd[pxq[6]] <= 1'b1;
            sc0 <= sc0 + {8'd0, xq[4:1]}; sc1 <= sc1 + {8'd0, xq[8:5]};
            if (sc0 == n_s) kdone[0] <= 1'b1;
            if (HEADS == 2 && sc1 == n_s) kdone[1] <= 1'b1;
            if (am_q[0]) begin if (am_q[1]) mc1 <= mc1 + 3'd1; else mc0 <= mc0 + 3'd1; end
            if (stl != 7'd0) stl <= stl - 7'd1;
            if (z_in) begin zp[zq[5:2]] <= 1'b1; zfw <= zfw + 5'd1; if (zfw[3:0] == zfr[3:0] && zfw[4] != zfr[4]) zovf <= 1'b1; end
            // sideband: lmax first, then the Z block sums, then Z done
            if (l_pend) begin
                ap[0] <= 1'b1;
                if (lh == 3'd3) begin lh <= 3'd0; lsent[lg] <= 1'b1; end else lh <= lh + 3'd1;
            end else if (z_emit) begin
                ap[0] <= 1'b1;
                if (zh == 2'd3) begin
                    zh <= 2'd0; zfr <= zfr + 5'd1;
                    if (z_hd[0]) zn1 <= zn1 + 5'd1; else zn0 <= zn0 + 5'd1;
                end else zh <= zh + 2'd1;
            end else if (zd0 || zd1) begin
                ap[0] <= 1'b1; zsent[zd1] <= 1'b1;
            end
            if (start) begin
                sc0 <= 12'd0; sc1 <= 12'd0; kdone <= 2'b00; lsent <= 2'b00; zsent <= 2'b00; pvd <= 2'b00; lh <= 3'd0;
                mc0 <= 3'd0; mc1 <= 3'd0; zn0 <= 5'd0; zn1 <= 5'd0; zfw <= 5'd0; zfr <= 5'd0; zh <= 2'd0; f <= 1'b0; zovf <= 1'b0; zp <= 16'd0;
                stl <= 7'd96;
            end
        end
    always @(posedge ck) begin
        lt[20:1] <= aq_q[20:1];
        qo[14:1] <= T; qo[533:16] <= aq_q[539:22]; qo[571:537] <= am_q[35:1];
        co[5:1] <= gmax_c;
        ap[564:46] <= {pvw, 1'b0, pxq[5:1], pxq[6]};
        // {so_data 32, so_any, so_k 4, so_hh 2, so_g, so_type 2}
        // a stack without a position has no maximum (the return chain may still hold the last layer's)
        if (l_pend) ap[42:1] <= {lm_s, xq[9 + lg] && n_s != 12'd0, 4'd0, lh[1:0], lg, 2'd0};
        else if (z_emit) ap[42:1] <= {z_s, 1'b1, z_hd[4:1], zh, z_hd[0], 2'd1};
        else ap[42:1] <= {32'd0, 1'b1, 4'd0, 2'd0, zd1, 2'd2};
    end
`ifdef KVD_AKDBG
    always @(posedge ck) begin
        if (rn_q && pv_bad) $display("AKDBG %m t=%0t P.V lanes apart: x %b beat %0d g %b, y %b beat %0d g %b", $time, pxq[0], pxq[5:1], pxq[6], pyq[0], pyq[5:1], pyq[6]);
        if (zovf) $display("AKDBG %m t=%0t Z queue overflow", $time);
        if (xq[0] | fx_q | fy_q | fz_q) $display("AKDBG %m t=%0t fault in: chain %b x %b y %b z %b", $time, xq[0], fx_q, fy_q, fz_q);
        if (start) $display("AKDBG %m t=%0t start T=%0d", $time, T);
    end
`endif
endmodule

module qkd_astk_ctl_tp8_cal #(
    parameter integer STATIC_SCHEDULE=0,
    parameter integer LMAX_START_AGE=0,
    parameter integer Z_START_AGE=0,
    parameter integer Z_STRIDE=4
) (
    input  wire [31:0]   cal,
    input  wire          ck,
    input  wire          rst_n,
    input  wire [1:0]    st,
    input  wire [539:0]  aq,
    output wire [20:0]   lt,
    input  wire [35:0]   am,
    output wire [564:0]  ap,
    output wire          af,
    output wire [571:0]  qo,
    input  wire [266:0]  xi,
    output wire [5:0]    co,
    input  wire [262:0]  px,
    input  wire [262:0]  py,
    input  wire [137:0]  zi,
    input  wire          fx,
    input  wire          fy,
    input  wire          fz
);
    qkd_astk_ctl_cal #(.HEADS(1), .STATIC_SCHEDULE(STATIC_SCHEDULE), .LMAX_START_AGE(LMAX_START_AGE),
        .Z_START_AGE(Z_START_AGE), .Z_STRIDE(Z_STRIDE)) u (.cal(cal), .ck(ck), .rst_n(rst_n), .st(st), .aq(aq), .lt(lt), .am(am), .ap(ap), .af(af), .qo(qo), .xi(xi),
        .co(co), .px(px), .py(py), .zi(zi), .fx(fx), .fy(fy), .fz(fz));
endmodule

module qkd_astk_native_stack_cal #(
 parameter integer RL=1,STATIC_SCHEDULE=1,
 parameter integer EXP_START_AGE=0,LMAX_START_AGE=0,Z_START_AGE=0,Z_STRIDE=4
)(
  input wire [47:0] cal,   // {EXP base, Z start, LMAX start} compiler calendar of this command
  input wire ck_c,
  input wire [3:0] ck_z,
  input wire [31:0] ck_x,
  input wire [7:0] ck_e,
  input wire ck_r,
  input wire rst_n,
  input wire [1:0] st,
  input wire [539:0] aq,
  input wire [35:0] am,
  output wire [562:0] ap,
  output wire af,
  output wire [20:0] lt,
  input wire er_v,
  input wire [10:0] er_addr,
  output wire er_rsp_v,
  output wire [10:0] er_rsp_addr,
  output wire [63:0] er_data,
  output wire [15:0] exp_committed,
  output wire score_committed,
  input wire [424:0] so0,
  input wire [424:0] so1,
  input wire [424:0] so2,
  input wire [424:0] so3,
  input wire [424:0] so4,
  input wire [424:0] so5,
  input wire [424:0] so6,
  input wire [424:0] so7,
  output wire [633:0] si0,
  output wire [633:0] si1,
  output wire [633:0] si2,
  output wire [633:0] si3,
  output wire [633:0] si4,
  output wire [633:0] si5,
  output wire [633:0] si6,
  output wire [633:0] si7
);
 wire [3399:0] raw_so={so7,so6,so5,so4,so3,so2,so1,so0},ep_so;
 wire [5071:0] ep_si,raw_si;
 wire er_fault;
 wire [7:0] ep_lane_fault;
 wire [31:0] ex_lane_fault;
 qkd_astk_native_er_service u_er(.ck(ck_r),.rst_n(rst_n),.read_v(er_v),.read_addr(er_addr),
  .engine_so(raw_so),.astk_so(ep_so),.astk_si(ep_si),.engine_si(raw_si),
  .response_v(er_rsp_v),.response_addr(er_rsp_addr),.response_data(er_data),.fault(er_fault));
 assign si0=raw_si[0+:634];
 assign si1=raw_si[634+:634];
 assign si2=raw_si[1268+:634];
 assign si3=raw_si[1902+:634];
 assign si4=raw_si[2536+:634];
 assign si5=raw_si[3170+:634];
 assign si6=raw_si[3804+:634];
 assign si7=raw_si[4438+:634];
 wire [571:0] cq;
 wire [266:0] cx;
 wire [137:0] czi;
 wire [564:0] full_ap;
 wire ctl_fault;
 qkd_astk_ctl_tp8_cal #(.STATIC_SCHEDULE(STATIC_SCHEDULE),.LMAX_START_AGE(LMAX_START_AGE),
  .Z_START_AGE(Z_START_AGE),.Z_STRIDE(Z_STRIDE)) u_ctl(.cal(cal[31:0]),.ck(ck_c),.rst_n(rst_n),.st(st),.aq(aq),.am(am),
  .lt(lt),.ap(full_ap),.af(ctl_fault),.qo(cq),.xi(cx),.co(),.px(263'd0),.py(263'd0),.zi(czi),.fx(1'b0),.fy(1'b0),.fz(zf[4]));
 assign ap={full_ap[564:45],full_ap[42:0]};
 assign score_committed=cq[534];
 wire [571:0] qi[0:8];
 wire [266:0] xo[0:8];
 wire [650:0] zo[0:8];
 wire [521:0] ro[0:8];
 assign xo[0]=0;assign zo[0]=0;
 ot_hdc_delay #(.W(572),.D(RL),.RESET(1)) u_cq(.clk(ck_r),.rst_n(rst_n),.d(cq),.q(qi[8]));
 ot_hdc_delay #(.W(267),.D(RL),.RESET(1)) u_cx(.clk(ck_r),.rst_n(rst_n),.d(xo[8]),.q(cx));
 assign ro[8]={zo[8][650:139],zo[8][10:7],zo[8][6:3],zo[8][2],zo[8][0]};
 genvar e,h,z;
 generate for(e=0;e<8;e=e+1)begin:g_ep
  wire [266:0] xi;
  wire [650:0] zi;
  wire [263:0] xa;
  wire [135:0] xe;
  ot_hdc_delay #(.W(267),.D(RL),.RESET(1)) u_x(.clk(ck_r),.rst_n(rst_n),.d(xo[e]),.q(xi));
  ot_hdc_delay #(.W(651),.D((e%2)?0:RL),.RESET(1)) u_z(.clk(ck_r),.rst_n(rst_n),.d(zo[e]),.q(zi));
  ot_hdc_delay #(.W(572),.D(RL),.RESET(1)) u_q(.clk(ck_r),.rst_n(rst_n),.d(qi[e+1]),.q(qi[e]));
  ot_hdc_delay #(.W(522),.D(RL),.RESET(1)) u_r(.clk(ck_r),.rst_n(rst_n),.d(ro[e+1]),.q(ro[e]));
  // Relative ages compensate command-chain skew and preserve the real chunk
  // chain's9edge joins plus the alternating RL relay. Profile trace must seal
  // these values against the selected native transport before qualification.
  qkd_astk_ep_cal #(.STATIC_SCHEDULE(STATIC_SCHEDULE),.HEADS(1),
   .EXP_START_AGE(EXP_START_AGE+9*e+RL*(e+e/2))) u_ep(.cal_exp(16'(cal[47:32]+9*e+RL*(e+e/2))),
   .ck(ck_e[e]),.rst_n(rst_n),.sq({st,3'(e)}),.so(ep_so[425*e+:425]),.si(ep_si[634*e+:634]),
   .qi(qi[e]),.xi(xi),.xo(xo[e+1]),.zi(zi),.zo(zo[e+1]),.ri(ro[e]),.xa(xa),.xe(xe),.cr(1'b0),
   .ui(536'd0),.uo(),.di(536'd0),.do_(),.pi(263'd0),.po(),.ci(6'd0),.co(),
   .kui(4'd0),.kuo(),.kdi(4'd0),.kdo(),.tui(1'b0),.tuo(),.tdi(1'b0),.tdo(),.fi(1'b0),.fo(ep_lane_fault[e]));
  for(h=0;h<4;h=h+1)begin:g_ex
   qkd_astk_ex u_ex(.ck(ck_x[4*e+h]),.rst_n(rst_n),.xa(xa[66*h+:66]),.xe(xe[34*h+:34]),
    .ui(536'd0),.uo(),.di(536'd0),.do_(),.pi(263'd0),.po(),.ci(6'd0),.co(),
    .kui(4'd0),.kuo(),.kdi(4'd0),.kdo(),.tui(1'b0),.tuo(),.tdi(1'b0),.tdo(),.fi(1'b0),.fo(ex_lane_fault[4*e+h]));
  end
 end endgenerate
 wire [137:0] zn[0:4];
 wire [4:0] zf;
 assign zf[0]=0;
 assign zn[0]={zo[8][138:11],zo[8][10:7],zo[8][6:3],zo[8][2],zo[8][0]};
 generate for(z=0;z<4;z=z+1)begin:g_zn
  qkd_astk_zn u_zn(.ck(ck_z[z]),.rst_n(rst_n),.zc({2'(z),st}),.tc(cq[14:0]),.zi(zn[z]),.zo(zn[z+1]),
   .fi(zf[z]),.fo(zf[z+1]));
 end endgenerate
 assign czi=zn[4];
 reg [15:0] visibility;
 integer n;
 always @*begin
  visibility=0;
  for(n=0;n<8;n=n+1)visibility=visibility|ep_si[634*n+537+:16];
 end
 assign exp_committed=visibility;
 reg visibility_fault;
 reg legacy_fault;
 integer lf;
 always @(posedge ck_r or negedge rst_n)
  if(!rst_n)legacy_fault<=0;else for(lf=0;lf<8;lf=lf+1)
   if(raw_so[425*lf+412])legacy_fault<=1;
 always @(posedge ck_r or negedge rst_n)
  if(!rst_n)visibility_fault<=0;else if(er_v&&!visibility[er_addr[6:3]])visibility_fault<=1;
 // Arithmetic errors and real SO fault return through EP XO bit0 into CTL.
 wire observed_fault=ctl_fault|er_fault|visibility_fault|legacy_fault|(|ep_lane_fault)|(|ex_lane_fault);
 reg retained_fault;
 always @(posedge ck_r or negedge rst_n)
  if(!rst_n)retained_fault<=0;else if(observed_fault)retained_fault<=1;
 assign af=observed_fault|retained_fault;
endmodule

module ot_qwen_tp8_attention_native_stack_cal #(
 parameter integer RL=1,QK_ISSUE_AGE=34,ROW_RETURN_LAT=9,
 parameter integer EXP_START_AGE=0,LMAX_START_AGE=0,Z_START_AGE=0,Z_STRIDE=4
)(
 input wire [47:0] cal,
 input wire [1:0] stack_id,
 input wire rst_n,
 input wire ck_astk_c,ck_astk_r,input wire[3:0] ck_astk_z,
 input wire[31:0] ck_astk_x,input wire[7:0] ck_astk_e,
 input wire[23:0] ck_ectl,input wire[2751:0] ck_head,
 input wire[539:0] aq,input wire[35:0] am,output wire[562:0] ap,
 input wire active_layer_parity,
 output wire[135:0] k_request,input wire[8199:0] k_response,
 input wire er_v,input wire[10:0] er_addr,
 output wire er_rsp_v,output wire[10:0] er_rsp_addr,output wire[63:0] er_data,
 output wire[15:0] exp_committed,output wire score_committed,output wire fault
);
 wire[3399:0] so;wire[5071:0] si;wire astk_fault;
 wire[20:0] lt;
 qkd_astk_native_stack_cal #(.RL(RL),.STATIC_SCHEDULE(1),
  .EXP_START_AGE(EXP_START_AGE),.LMAX_START_AGE(LMAX_START_AGE),
  .Z_START_AGE(Z_START_AGE),.Z_STRIDE(Z_STRIDE)) u_astk(.cal(cal),
  .ck_c(ck_astk_c),.ck_z(ck_astk_z),.ck_x(ck_astk_x),.ck_e(ck_astk_e),.ck_r(ck_astk_r),
  .rst_n(rst_n),.st(stack_id),.aq(aq),.am(am),.ap(ap),.af(astk_fault),.lt(lt),
  .er_v(er_v),.er_addr(er_addr),.er_rsp_v(er_rsp_v),.er_rsp_addr(er_rsp_addr),.er_data(er_data),
  .exp_committed(exp_committed),.score_committed(score_committed),
  .so0(so[0+:425]),.so1(so[425+:425]),.so2(so[850+:425]),.so3(so[1275+:425]),
